-- The centre of every forward sortation area (FSA, a postal code's first three characters, #181):
-- what the carpool board (#180) measures detours with. Reference data, read only by
-- public.carpool_board() (SECURITY DEFINER): it lives in `private`, out of the API, and the board
-- returns detours in km, never coordinates.
--
-- Source: Statistics Canada, 2021 Census forward sortation area boundary file, under the Open
-- Government Licence - Canada. One point per FSA, the area-weighted centroid of its polygons;
-- generated by scripts/postal-fsa/centres.py, which says how. A rural FSA covers a large area,
-- so its centre is rough; an urban one is a neighbourhood.

CREATE TABLE private.postal_fsa (
    fsa text PRIMARY KEY CHECK (fsa ~ '^[ABCEGHJ-NPRSTVXY][0-9][ABCEGHJ-NPRSTV-Z]$'),
    lat double precision NOT NULL CHECK (lat BETWEEN -90 AND 90),
    lng double precision NOT NULL CHECK (lng BETWEEN -180 AND 180)
);

COMMENT ON TABLE private.postal_fsa IS
    'Centre of each Canadian FSA (Statistics Canada 2021 boundary file, OGL-Canada), for carpool detours (#180). Not exposed through the API.';

REVOKE ALL ON TABLE private.postal_fsa FROM PUBLIC;

;
